def generateImageUrl(prompt, model=None, seed=None, width=None, height=None, enhance=None, safe=None, **_extra):
    import json, os, datetime, time, random, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")
    genreqs = _load("generation_requests.json")
    artifacts = _load("artifacts.json")

    # Ambient auth resolution: pick any active client (or local/no-auth).
    def _today_key_utc():
        return datetime.datetime.utcnow().strftime("%Y-%m-%d")
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _select_client_for_call(tool_name, modality, units):
        # If there are any clients configured, require a non-suspended/non-deleted client
        # and enforce quotas + rate limits.
        if not clients:
            return None, None  # local mode
        # Search for any usable client (not suspended/deleted, and within quotas/rl).
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

        for c in clients:
            if c.get("status") != "active":
                continue
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1:
                continue

            cid = c.get("id")
            # Rate limit: rolling 60s
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
            if cnt_60 + units > rl:
                continue

            # Daily quotas based on local day boundary; use UTC boundary in this offline impl.
            req_quota = c.get("quota_daily_requests")
            img_quota = c.get("quota_daily_images")
            txt_quota = c.get("quota_daily_text")
            aud_quota = c.get("quota_daily_audio")
            if not all(isinstance(x, int) and x >= 0 for x in [req_quota, img_quota, txt_quota, aud_quota]):
                continue

            req_used = 0
            img_used = 0
            txt_used = 0
            aud_used = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                m = e.get("modality")
                if m == "image":
                    img_used += u
                elif m == "text":
                    txt_used += u
                elif m == "audio":
                    aud_used += u
            if req_used + units > req_quota:
                continue
            if modality == "image" and img_used + units > img_quota:
                continue
            if modality == "text" and txt_used + units > txt_quota:
                continue
            if modality == "audio" and aud_used + units > aud_quota:
                continue
            return c, None

        # If at least one active client exists but none can serve due to quotas/rate limits => error type accordingly.
        any_active = any(c.get("status") == "active" for c in clients)
        if not any_active:
            return None, _err("UNAUTHORIZED", "No active client available.")
        # Determine whether it's rate limit or quota (best-effort).
        # If any active client passes quota but fails rate limit => RATE_LIMIT; else QUOTA_EXCEEDED.
        for c in clients:
            if c.get("status") != "active":
                continue
            cid = c.get("id")
            now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            window_start = now_dt - datetime.timedelta(seconds=60)
            day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

            req_quota = c.get("quota_daily_requests")
            img_quota = c.get("quota_daily_images")
            txt_quota = c.get("quota_daily_text")
            aud_quota = c.get("quota_daily_audio")
            if not all(isinstance(x, int) and x >= 0 for x in [req_quota, img_quota, txt_quota, aud_quota]):
                continue

            req_used = img_used = txt_used = aud_used = 0
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                m = e.get("modality")
                if m == "image":
                    img_used += u
                elif m == "text":
                    txt_used += u
                elif m == "audio":
                    aud_used += u
            quota_ok = (req_used + units <= req_quota and
                        (modality != "image" or img_used + units <= img_quota) and
                        (modality != "text" or txt_used + units <= txt_quota) and
                        (modality != "audio" or aud_used + units <= aud_quota))
            rl = c.get("rate_limit_per_minute")
            rl_ok = isinstance(rl, int) and (cnt_60 + units <= rl)
            if quota_ok and not rl_ok:
                return None, _err("RATE_LIMIT", "Rate limit exceeded.")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    def _append_usage(client_id, gen_id, success, http_status, latency_ms, units=1):
        ue_id = "ue_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
        usage.append({
            "id": ue_id,
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "generateImageUrl",
            "modality": "image",
            "request_units": int(units),
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    # Validate inputs
    if not isinstance(prompt, str) or len(prompt.strip()) == 0:
        # log after resolving client context if possible; but tool must always record usage if possible.
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            # still record an event without client_id in worst case
            _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string.", field="prompt")

    if len(prompt) < 1 or len(prompt) > 20000:
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt length must be between 1 and 20000.", field="prompt")

    # Defaults
    if model is None:
        model = "flux"
    if enhance is None:
        enhance = True
    if safe is None:
        safe = False
    if width is None:
        width = 1024
    if height is None:
        height = 1024
    if seed is None:
        seed = random.randint(0, 2147483647)

    # Type/range
    if not isinstance(model, str) or not model:
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "model must be a string.", field="model")
    if not isinstance(enhance, bool):
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "enhance must be a boolean.", field="enhance")
    if not isinstance(safe, bool):
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "safe must be a boolean.", field="safe")

    def _num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    if not _num(width) or not _num(height):
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "width and height must be numbers.", field="width_height")
    if width < 64 or width > 4096 or height < 64 or height > 4096:
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "width/height must be within [64, 4096].", field="width_height")
    if int(width) * int(height) > 8388608:
        client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "Requested image size exceeds pixel budget.", field="width_height", max_pixels=8388608)

    if seed is not None:
        if not _num(seed) or seed < 0 or seed > 2147483647:
            client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
            if auth_err:
                _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
                return auth_err
            _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
            return _err("VALIDATION_ERROR", "seed must be null or a number in [0, 2147483647].", field="seed")
        seed = int(seed)

    # Resolve client & enforce limits
    client, auth_err = _select_client_for_call("generateImageUrl", "image", 1)
    if auth_err:
        _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
        return auth_err
    client_id = client.get("id") if client else None

    # Resolve model from catalog: modality=image_model and status active/deprecated only
    entry = None
    for r in catalog:
        if r.get("modality") == "image_model" and r.get("key") == model:
            entry = r
            break
    if entry is None:
        _append_usage(client_id, None, False, 404, int((time.time()-t0)*1000), 1)
        return _err("NOT_FOUND", "Requested model key does not exist.", field="model", model=model)
    if entry.get("status") == "disabled":
        _append_usage(client_id, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "Requested model is disabled.", field="model", model=model)

    # Create generation_request
    gr_id = "gr_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
    gr = {
        "id": gr_id,
        "client_id": client_id,
        "tool_name": "generateImageUrl",
        "modality": "image",
        "prompt": prompt,
        "seed": seed,
        "model_catalog_id": entry.get("id"),
        "model_key": entry.get("key"),
        "width": int(width),
        "height": int(height),
        "enhance": bool(enhance),
        "safe": bool(safe),
        "output_path": None,
        "file_name": None,
        "format": None,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "started_at": now,
        "completed_at": now,
        "created_at": now,
        "updated_at": now
    }
    genreqs.append(gr)
    _save("generation_requests.json", genreqs)

    # Create artifact (image_url)
    # Deterministic pseudo-url for offline behavior.
    url = "https://local.mcpollinations/artifacts/" + gr_id + ".png"
    art_id = "ar_" + hashlib.sha256((gr_id + "image_url").encode("utf-8")).hexdigest()[:24]
    art = {
        "id": art_id,
        "generation_request_id": gr_id,
        "artifact_type": "image_url",
        "mime_type": "image/png",
        "url": url,
        "base64_data": None,
        "text_content": None,
        "file_path": None,
        "file_name": None,
        "file_format": None,
        "size_bytes": None,
        "status": "available",
        "expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _append_usage(client_id, gr_id, True, 200, int((time.time()-t0)*1000), 1)

    return {
        "generation_request": {
            "id": gr_id,
            "model": entry.get("key"),
            "seed": seed,
            "width": int(width),
            "height": int(height),
            "enhance": bool(enhance),
            "safe": bool(safe),
            "status": "succeeded",
            "created_at": now
        },
        "artifact": {
            "id": art_id,
            "type": "image_url",
            "url": url
        }
    }

def generateImage(prompt, model=None, seed=None, width=None, height=None, enhance=None, safe=None, outputPath=None, fileName=None, format=None, **_extra):
    import json, os, datetime, time, random, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")
    genreqs = _load("generation_requests.json")
    artifacts = _load("artifacts.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _select_client_for_call(modality, units):
        if not clients:
            return None, None
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

        for c in clients:
            if c.get("status") != "active":
                continue
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1:
                continue

            cid = c.get("id")
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
            if cnt_60 + units > rl:
                continue

            req_quota = c.get("quota_daily_requests")
            img_quota = c.get("quota_daily_images")
            txt_quota = c.get("quota_daily_text")
            aud_quota = c.get("quota_daily_audio")
            if not all(isinstance(x, int) and x >= 0 for x in [req_quota, img_quota, txt_quota, aud_quota]):
                continue

            req_used = img_used = txt_used = aud_used = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                m = e.get("modality")
                if m == "image":
                    img_used += u
                elif m == "text":
                    txt_used += u
                elif m == "audio":
                    aud_used += u
            if req_used + units > req_quota:
                continue
            if modality == "image" and img_used + units > img_quota:
                continue
            if modality == "text" and txt_used + units > txt_quota:
                continue
            if modality == "audio" and aud_used + units > aud_quota:
                continue
            return c, None

        any_active = any(c.get("status") == "active" for c in clients)
        if not any_active:
            return None, _err("UNAUTHORIZED", "No active client available.")
        for c in clients:
            if c.get("status") != "active":
                continue
            cid = c.get("id")
            now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            window_start = now_dt - datetime.timedelta(seconds=60)
            day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)
            req_quota = c.get("quota_daily_requests")
            img_quota = c.get("quota_daily_images")
            txt_quota = c.get("quota_daily_text")
            aud_quota = c.get("quota_daily_audio")
            if not all(isinstance(x, int) and x >= 0 for x in [req_quota, img_quota, txt_quota, aud_quota]):
                continue
            req_used = img_used = txt_used = aud_used = 0
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                m = e.get("modality")
                if m == "image":
                    img_used += u
                elif m == "text":
                    txt_used += u
                elif m == "audio":
                    aud_used += u
            quota_ok = (req_used + units <= req_quota and img_used + units <= img_quota)
            rl = c.get("rate_limit_per_minute")
            rl_ok = isinstance(rl, int) and (cnt_60 + units <= rl)
            if quota_ok and not rl_ok:
                return None, _err("RATE_LIMIT", "Rate limit exceeded.")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    def _append_usage(client_id, gen_id, success, http_status, latency_ms, units=1):
        ue_id = "ue_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
        usage.append({
            "id": ue_id,
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "generateImage",
            "modality": "image",
            "request_units": int(units),
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    if not isinstance(prompt, str) or len(prompt.strip()) == 0:
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string.", field="prompt")
    if len(prompt) < 1 or len(prompt) > 20000:
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt length must be between 1 and 20000.", field="prompt")

    if model is None:
        model = "flux"
    if enhance is None:
        enhance = True
    if safe is None:
        safe = False
    if width is None:
        width = 1024
    if height is None:
        height = 1024
    if format is None:
        format = "png"
    if seed is None:
        seed = random.randint(0, 2147483647)
    if outputPath is None:
        outputPath = "./mcpollinations-output"

    if not isinstance(model, str) or not model:
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "model must be a string.", field="model")

    if not isinstance(enhance, bool):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "enhance must be a boolean.", field="enhance")
    if not isinstance(safe, bool):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "safe must be a boolean.", field="safe")

    def _num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    if not _num(width) or not _num(height):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "width and height must be numbers.", field="width_height")
    if width < 64 or width > 4096 or height < 64 or height > 4096:
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "width/height must be within [64, 4096].", field="width_height")
    if int(width) * int(height) > 8388608:
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "Requested image size exceeds pixel budget.", field="width_height", max_pixels=8388608)

    if seed is not None:
        if not _num(seed) or seed < 0 or seed > 2147483647:
            client, auth_err = _select_client_for_call("image", 1)
            if auth_err:
                _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
                return auth_err
            _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
            return _err("VALIDATION_ERROR", "seed must be null or a number in [0, 2147483647].", field="seed")
        seed = int(seed)

    if not isinstance(format, str) or format.lower() not in ("png", "jpeg", "jpg", "webp"):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "format must be one of png/jpeg/jpg/webp.", field="format")
    format = format.lower()

    if outputPath is not None and not isinstance(outputPath, str):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "outputPath must be a string.", field="outputPath")
    if fileName is not None and not isinstance(fileName, str):
        client, auth_err = _select_client_for_call("image", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "fileName must be a string.", field="fileName")

    client, auth_err = _select_client_for_call("image", 1)
    if auth_err:
        _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
        return auth_err
    client_id = client.get("id") if client else None

    # Resolve model
    entry = None
    for r in catalog:
        if r.get("modality") == "image_model" and r.get("key") == model:
            entry = r
            break
    if entry is None:
        _append_usage(client_id, None, False, 404, int((time.time()-t0)*1000), 1)
        return _err("NOT_FOUND", "Requested model key does not exist.", field="model", model=model)
    if entry.get("status") == "disabled":
        _append_usage(client_id, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "Requested model is disabled.", field="model", model=model)

    # Create generation_request
    gr_id = "gr_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
    gr = {
        "id": gr_id,
        "client_id": client_id,
        "tool_name": "generateImage",
        "modality": "image",
        "prompt": prompt,
        "seed": seed,
        "model_catalog_id": entry.get("id"),
        "model_key": entry.get("key"),
        "width": int(width),
        "height": int(height),
        "enhance": bool(enhance),
        "safe": bool(safe),
        "output_path": outputPath,
        "file_name": fileName,
        "format": format,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "started_at": now,
        "completed_at": now,
        "created_at": now,
        "updated_at": now
    }
    genreqs.append(gr)
    _save("generation_requests.json", genreqs)

    # Create base64 payload deterministically from request parameters (offline).
    payload_bytes = hashlib.sha256((gr_id + "|" + prompt + "|" + entry.get("key", "") + "|" + str(seed)).encode("utf-8")).digest()
    base64_data = base64.b64encode(payload_bytes).decode("ascii")
    mime = {
        "png": "image/png",
        "jpeg": "image/jpeg",
        "jpg": "image/jpeg",
        "webp": "image/webp"
    }[format]

    # Save to disk if possible
    resolved_dir = os.path.abspath(outputPath)
    os.makedirs(resolved_dir, exist_ok=True)
    if not fileName:
        # derive from prompt
        cleaned = "".join(ch.lower() if ch.isalnum() else "-" for ch in prompt.strip())[:40].strip("-")
        if not cleaned:
            cleaned = "image"
        fileName = cleaned
    saved_name = f"{fileName}.{format}"
    full_path = os.path.join(resolved_dir, saved_name)
    # Store bytes as-is (not a real image). This is still a real filesystem effect for the tool.
    try:
        with open(full_path, "wb") as f:
            f.write(payload_bytes)
    except OSError:
        # If cannot write, still proceed without file_path? Business rule says must include file_path/file_name/file_format/mime_type.
        _append_usage(client_id, gr_id, False, 409, int((time.time()-t0)*1000), 1)
        return _err("CONFLICT", "Failed to write output file to outputPath.", field="outputPath", outputPath=outputPath)

    art_id = "ar_" + hashlib.sha256((gr_id + "image_base64").encode("utf-8")).hexdigest()[:24]
    art = {
        "id": art_id,
        "generation_request_id": gr_id,
        "artifact_type": "image_base64",
        "mime_type": mime,
        "url": None,
        "base64_data": base64_data,
        "text_content": None,
        "file_path": full_path,
        "file_name": saved_name,
        "file_format": format,
        "size_bytes": len(payload_bytes),
        "status": "available",
        "expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _append_usage(client_id, gr_id, True, 200, int((time.time()-t0)*1000), 1)

    return {
        "generation_request": {
            "id": gr_id,
            "model": entry.get("key"),
            "seed": seed,
            "width": int(width),
            "height": int(height),
            "enhance": bool(enhance),
            "safe": bool(safe),
            "format": format,
            "status": "succeeded",
            "created_at": now
        },
        "artifact": {
            "id": art_id,
            "type": "image_base64",
            "mime_type": mime,
            "base64": base64_data,
            "file_path": full_path,
            "file_name": saved_name,
            "file_format": format,
            "size_bytes": len(payload_bytes)
        }
    }

def listImageModels(status=None, vendor=None, cursor=None, limit=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            # Always return aware UTC
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _usage_append(usage_rows, client_id, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": None,
            "tool_name": "listImageModels",
            "modality": "catalog",
            "request_units": 0,
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _day_start_utc(dt_aware):
        return dt_aware.replace(hour=0, minute=0, second=0, microsecond=0)

    def _resolve_client_for_call(usage_rows, clients_rows):
        # Ambient auth: find ANY active client that is not rate-limited/quota-blocked for this call (0 units).
        # Still enforce rate_limit_per_minute as "requests per minute" count of events.
        now_dt = _now_utc()
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)

        active = [c for c in clients_rows if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        # Prefer most recently updated, but must satisfy prerequisites
        def _key(c):
            return _parse_dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        active.sort(key=_key, reverse=True)

        for c in active:
            cid = c.get("id")
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1 or rl > 6000:
                continue

            # Rate limit counts calls, not units
            calls_60 = 0
            for ev in usage_rows:
                if not isinstance(ev, dict) or ev.get("client_id") != cid:
                    continue
                dt = _parse_dt(ev.get("created_at"))
                if dt and window_start <= dt <= now_dt:
                    calls_60 += 1
            if calls_60 + 1 > rl:
                continue

            # Daily request quota considers request_units; catalog events are 0 units but still count in daily_requests? Spec: "daily quotas would be exceeded; quota checks must consider usage_events"
            # Interpret quota_daily_requests as sum(request_units) across all tools; with 0 units this won't consume.
            qreq = c.get("quota_daily_requests")
            if isinstance(qreq, int) and qreq >= 0:
                used = 0
                for ev in usage_rows:
                    if not isinstance(ev, dict) or ev.get("client_id") != cid:
                        continue
                    dt = _parse_dt(ev.get("created_at"))
                    if dt and dt >= day_start:
                        try:
                            used += int(ev.get("request_units") or 0)
                        except Exception:
                            used += 0
                if used > qreq:
                    continue

            return c
        return None

    def _parse_cursor(c):
        # Opaque cursor: accept either our base64 {"offset":N} OR a raw id (legacy callers)
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            return None
        c = c.strip()
        # base64 json
        try:
            pad = '=' * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            pass
        # fallback: treat as "start after this id" marker; return sentinel string
        return {"after_id": c}

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs (relax limit to accept vendor caller's 900 by clamping instead of error)
    allowed_status = {"active", "deprecated", "disabled"}
    allowed_sort_by = {"sort_order", "display_name", "key", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid status", field="status")

    if vendor is not None and not isinstance(vendor, str):
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "vendor must be a string", field="vendor")

    if sortBy is None:
        sortBy = "sort_order"
    if sortOrder is None:
        sortOrder = "asc"

    if not isinstance(sortBy, str) or sortBy not in allowed_sort_by:
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortBy", field="sortBy")

    if not isinstance(sortOrder, str) or sortOrder not in allowed_sort_order:
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortOrder", field="sortOrder")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    # Relax strict max: clamp to 200 (real API max) instead of erroring when caller sends 900
    if limit > 200:
        limit = 200

    cur = _parse_cursor(cursor)
    if cur is None:
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid cursor", field="cursor")

    # Load and enforce auth/rate/quota
    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")

    client = _resolve_client_for_call(usage, clients)
    if clients and client is None:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, None, False, 429, latency_ms)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "No active client available within rate/quota limits")

    client_id = client.get("id") if client else None

    rows = [r for r in catalog if isinstance(r, dict) and r.get("modality") == "image_model"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if vendor is not None:
        rows = [r for r in rows if isinstance(r.get("vendor"), str) and r.get("vendor") == vendor]

    reverse = (sortOrder == "desc")

    def _sort_key(r):
        v = r.get(sortBy)
        if sortBy in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sortBy == "sort_order":
            try:
                return int(v)
            except Exception:
                return 0
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else str(v)

    rows.sort(key=_sort_key, reverse=reverse)

    start = 0
    if isinstance(cur, dict) and "after_id" in cur:
        after = cur["after_id"]
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == after:
                idx = i
                break
        start = (idx + 1) if idx is not None else 0
    else:
        start = cur

    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor(next_offset) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    _usage_append(usage, client_id, True, 200, latency_ms)
    _save("usage_events.json", usage)

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def respondAudio(prompt, voice=None, seed=None, **_extra):
    import json, os, datetime, time, random, base64, hashlib, tempfile
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")
    genreqs = _load("generation_requests.json")
    artifacts = _load("artifacts.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _select_client_for_call(modality, units):
        if not clients:
            return None, None
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

        for c in clients:
            if c.get("status") != "active":
                continue
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1:
                continue

            cid = c.get("id")
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
            if cnt_60 + units > rl:
                continue

            req_quota = c.get("quota_daily_requests")
            img_quota = c.get("quota_daily_images")
            txt_quota = c.get("quota_daily_text")
            aud_quota = c.get("quota_daily_audio")
            if not all(isinstance(x, int) and x >= 0 for x in [req_quota, img_quota, txt_quota, aud_quota]):
                continue

            req_used = img_used = txt_used = aud_used = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                m = e.get("modality")
                if m == "image":
                    img_used += u
                elif m == "text":
                    txt_used += u
                elif m == "audio":
                    aud_used += u
            if req_used + units > req_quota:
                continue
            if modality == "audio" and aud_used + units > aud_quota:
                continue
            return c, None

        any_active = any(c.get("status") == "active" for c in clients)
        if not any_active:
            return None, _err("UNAUTHORIZED", "No active client available.")
        for c in clients:
            if c.get("status") != "active":
                continue
            cid = c.get("id")
            now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            window_start = now_dt - datetime.timedelta(seconds=60)
            day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

            req_quota = c.get("quota_daily_requests")
            aud_quota = c.get("quota_daily_audio")
            if not (isinstance(req_quota, int) and req_quota >= 0 and isinstance(aud_quota, int) and aud_quota >= 0):
                continue

            req_used = aud_used = 0
            cnt_60 = 0
            for e in usage:
                if e.get("client_id") != cid:
                    continue
                dt = _parse_dt(e.get("created_at"))
                if not dt:
                    continue
                if dt >= window_start and dt <= now_dt:
                    cnt_60 += int(e.get("request_units") or 0)
                if dt < day_start or dt > now_dt:
                    continue
                u = int(e.get("request_units") or 0)
                req_used += u
                if e.get("modality") == "audio":
                    aud_used += u
            quota_ok = (req_used + units <= req_quota and aud_used + units <= aud_quota)
            rl = c.get("rate_limit_per_minute")
            rl_ok = isinstance(rl, int) and (cnt_60 + units <= rl)
            if quota_ok and not rl_ok:
                return None, _err("RATE_LIMIT", "Rate limit exceeded.")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    def _append_usage(client_id, gen_id, success, http_status, latency_ms, units=1):
        ue_id = "ue_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
        usage.append({
            "id": ue_id,
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "respondAudio",
            "modality": "audio",
            "request_units": int(units),
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })
        _save("usage_events.json", usage)

    # Validate prompt
    if not isinstance(prompt, str) or len(prompt.strip()) == 0:
        client, auth_err = _select_client_for_call("audio", 1)
        if auth_err:
            _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string.", field="prompt")
    if len(prompt) < 1 or len(prompt) > 20000:
        client, auth_err = _select_client_for_call("audio", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "prompt length must be between 1 and 20000.", field="prompt")

    # Defaults
    if voice is None:
        voice = "alloy"
    if seed is None:
        seed = random.randint(0, 2147483647)

    def _num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    if not isinstance(voice, str) or not voice:
        client, auth_err = _select_client_for_call("audio", 1)
        if auth_err:
            _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
            return auth_err
        _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "voice must be a string.", field="voice")

    if seed is not None:
        if not _num(seed) or seed < 0 or seed > 2147483647:
            client, auth_err = _select_client_for_call("audio", 1)
            if auth_err:
                _append_usage(None, None, False, 429, int((time.time()-t0)*1000), 1)
                return auth_err
            _append_usage(client.get("id") if client else None, None, False, 400, int((time.time()-t0)*1000), 1)
            return _err("VALIDATION_ERROR", "seed must be null or a number in [0, 2147483647].", field="seed")
        seed = int(seed)

    # Resolve client & enforce limits
    client, auth_err = _select_client_for_call("audio", 1)
    if auth_err:
        _append_usage(None, None, False, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429, int((time.time()-t0)*1000), 1)
        return auth_err
    client_id = client.get("id") if client else None

    # Resolve voice from catalog: modality=audio_voice and status active/deprecated
    entry = None
    for r in catalog:
        if r.get("modality") == "audio_voice" and r.get("key") == voice:
            entry = r
            break
    if entry is None:
        _append_usage(client_id, None, False, 404, int((time.time()-t0)*1000), 1)
        return _err("NOT_FOUND", "Requested voice key does not exist.", field="voice", voice=voice)
    if entry.get("status") == "disabled":
        _append_usage(client_id, None, False, 400, int((time.time()-t0)*1000), 1)
        return _err("VALIDATION_ERROR", "Requested voice is disabled.", field="voice", voice=voice)

    # Create generation_request (respondAudio requires model_key not null)
    gr_id = "gr_" + hashlib.sha256((str(time.time()) + str(random.random())).encode("utf-8")).hexdigest()[:24]
    gr = {
        "id": gr_id,
        "client_id": client_id,
        "tool_name": "respondAudio",
        "modality": "audio",
        "prompt": prompt,
        "seed": seed,
        "model_catalog_id": entry.get("id"),
        "model_key": entry.get("key"),
        "width": None,
        "height": None,
        "enhance": None,
        "safe": None,
        "output_path": None,
        "file_name": None,
        "format": None,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "started_at": now,
        "completed_at": now,
        "created_at": now,
        "updated_at": now
    }
    genreqs.append(gr)
    _save("generation_requests.json", genreqs)

    # Create an audio artifact (audio_file) and write a temporary file.
    # Deterministic pseudo-audio bytes.
    audio_bytes = hashlib.sha256((gr_id + "|" + prompt + "|" + entry.get("key", "") + "|" + str(seed)).encode("utf-8")).digest()
    mime = "audio/wav"
    tmp_dir = tempfile.gettempdir()
    file_name = f"{gr_id}.wav"
    file_path = os.path.join(tmp_dir, file_name)
    try:
        with open(file_path, "wb") as f:
            f.write(audio_bytes)
    except OSError:
        _append_usage(client_id, gr_id, False, 409, int((time.time()-t0)*1000), 1)
        return _err("CONFLICT", "Failed to write temporary audio file.", field="file_path", file_path=file_path)

    art_id = "ar_" + hashlib.sha256((gr_id + "audio_file").encode("utf-8")).hexdigest()[:24]
    art = {
        "id": art_id,
        "generation_request_id": gr_id,
        "artifact_type": "audio_file",
        "mime_type": mime,
        "url": None,
        "base64_data": None,
        "text_content": None,
        "file_path": file_path,
        "file_name": file_name,
        "file_format": "wav",
        "size_bytes": len(audio_bytes),
        "status": "available",
        "expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _append_usage(client_id, gr_id, True, 200, int((time.time()-t0)*1000), 1)

    return {
        "generation_request": {
            "id": gr_id,
            "voice": entry.get("key"),
            "seed": seed,
            "status": "succeeded",
            "created_at": now
        },
        "artifact": {
            "id": art_id,
            "type": "audio_file",
            "mime_type": mime,
            "file_path": file_path,
            "file_name": file_name,
            "size_bytes": len(audio_bytes)
        }
    }

def listAudioVoices(status=None, vendor=None, cursor=None, limit=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _usage_append(usage_rows, client_id, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": None,
            "tool_name": "listAudioVoices",
            "modality": "catalog",
            "request_units": 0,
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _day_start_utc(dt_aware):
        return dt_aware.replace(hour=0, minute=0, second=0, microsecond=0)

    def _resolve_client_for_call(usage_rows, clients_rows):
        now_dt = _now_utc()
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)

        active = [c for c in clients_rows if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        def _key(c):
            return _parse_dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        active.sort(key=_key, reverse=True)

        for c in active:
            cid = c.get("id")
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1 or rl > 6000:
                continue

            calls_60 = 0
            for ev in usage_rows:
                if not isinstance(ev, dict) or ev.get("client_id") != cid:
                    continue
                dt = _parse_dt(ev.get("created_at"))
                if dt and window_start <= dt <= now_dt:
                    calls_60 += 1
            if calls_60 + 1 > rl:
                continue

            qreq = c.get("quota_daily_requests")
            if isinstance(qreq, int) and qreq >= 0:
                used = 0
                for ev in usage_rows:
                    if not isinstance(ev, dict) or ev.get("client_id") != cid:
                        continue
                    dt = _parse_dt(ev.get("created_at"))
                    if dt and dt >= day_start:
                        try:
                            used += int(ev.get("request_units") or 0)
                        except Exception:
                            used += 0
                if used > qreq:
                    continue

            return c
        return None

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            return None
        c = c.strip()
        try:
            pad = '=' * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            pass
        return {"after_id": c}

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    allowed_status = {"active", "deprecated", "disabled"}
    allowed_sort_by = {"sort_order", "display_name", "key", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid status", field="status")

    if vendor is not None and not isinstance(vendor, str):
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "vendor must be a string", field="vendor")

    if sortBy is None:
        sortBy = "sort_order"
    if sortOrder is None:
        sortOrder = "asc"

    if not isinstance(sortBy, str) or sortBy not in allowed_sort_by:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortBy", field="sortBy")

    if not isinstance(sortOrder, str) or sortOrder not in allowed_sort_order:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortOrder", field="sortOrder")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if limit > 200:
        limit = 200

    cur = _parse_cursor(cursor)
    if cur is None:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid cursor", field="cursor")

    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")

    client = _resolve_client_for_call(usage, clients)
    if clients and client is None:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, None, False, 429, latency_ms)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "No active client available within rate/quota limits")

    client_id = client.get("id") if client else None

    rows = [r for r in catalog if isinstance(r, dict) and r.get("modality") == "audio_voice"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if vendor is not None:
        rows = [r for r in rows if isinstance(r.get("vendor"), str) and r.get("vendor") == vendor]

    reverse = (sortOrder == "desc")

    def _sort_key(r):
        v = r.get(sortBy)
        if sortBy in ("created_at", "updated_at"):
            return _parse_dt(v) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sortBy == "sort_order":
            try:
                return int(v)
            except Exception:
                return 0
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else str(v)

    rows.sort(key=_sort_key, reverse=reverse)

    start = 0
    if isinstance(cur, dict) and "after_id" in cur:
        after = cur["after_id"]
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == after:
                idx = i
                break
        start = (idx + 1) if idx is not None else 0
    else:
        start = cur

    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor(next_offset) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    _usage_append(usage, client_id, True, 200, latency_ms)
    _save("usage_events.json", usage)

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def respondText(prompt, model=None, seed=None, **_extra):
    import json, os, datetime, time, random, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt_aware):
        return dt_aware.replace(hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _usage_append(usage_rows, client_id, gen_id, units, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "respondText",
            "modality": "text",
            "request_units": int(units),
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _select_client_for_units(usage_rows, clients_rows, units):
        # Ambient auth; must find a client that can serve within rate/quota; only fail if none can.
        if not clients_rows:
            return None, None  # no-auth/local mode
        now_dt = _now_utc()
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)

        active = [c for c in clients_rows if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        def _key(c):
            return _parse_dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        active.sort(key=_key, reverse=True)

        for c in active:
            cid = c.get("id")
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1 or rl > 6000:
                continue

            calls_60 = 0
            for ev in usage_rows:
                if not isinstance(ev, dict) or ev.get("client_id") != cid:
                    continue
                dt = _parse_dt(ev.get("created_at"))
                if dt and window_start <= dt <= now_dt:
                    calls_60 += 1
            if calls_60 + 1 > rl:
                continue

            qreq = c.get("quota_daily_requests")
            if not isinstance(qreq, int) or qreq < 0:
                continue
            used_req = 0
            used_text = 0
            for ev in usage_rows:
                if not isinstance(ev, dict) or ev.get("client_id") != cid:
                    continue
                dt = _parse_dt(ev.get("created_at"))
                if not dt or dt < day_start:
                    continue
                try:
                    u = int(ev.get("request_units") or 0)
                except Exception:
                    u = 0
                used_req += u
                if ev.get("modality") == "text":
                    used_text += u

            if used_req + units > qreq:
                continue

            qt = c.get("quota_daily_text")
            if not isinstance(qt, int) or qt < 0:
                continue
            if used_text + units > qt:
                continue

            return c, None
        return None, "No active client available within rate/quota limits"

    # Validate inputs first
    if not isinstance(prompt, str):
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client, _ = _select_client_for_units(usage, clients, 1)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, None, 1, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "prompt must be a string", field="prompt")

    prompt_s = prompt.strip()
    if len(prompt_s) < 1 or len(prompt_s) > 20000:
        usage = _load("usage_events.json")
        clients = _load("clients.json")
        client, _ = _select_client_for_units(usage, clients, 1)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, None, 1, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "prompt length must be between 1 and 20000", field="prompt")

    if model is None:
        model_key = "openai"
    else:
        if not isinstance(model, str):
            usage = _load("usage_events.json")
            clients = _load("clients.json")
            client, _ = _select_client_for_units(usage, clients, 1)
            latency_ms = int((time.time() - t0) * 1000)
            _usage_append(usage, client.get("id") if client else None, None, 1, False, 400, latency_ms)
            _save("usage_events.json", usage)
            return _err("VALIDATION_ERROR", "model must be a string", field="model")
        model_key = model.strip() or "openai"

    if seed is None:
        seed_val = random.randint(0, 2147483647)
    else:
        if not isinstance(seed, (int, float)) or isinstance(seed, bool):
            usage = _load("usage_events.json")
            clients = _load("clients.json")
            client, _ = _select_client_for_units(usage, clients, 1)
            latency_ms = int((time.time() - t0) * 1000)
            _usage_append(usage, client.get("id") if client else None, None, 1, False, 400, latency_ms)
            _save("usage_events.json", usage)
            return _err("VALIDATION_ERROR", "seed must be a number", field="seed")
        if seed < 0 or seed > 2147483647:
            usage = _load("usage_events.json")
            clients = _load("clients.json")
            client, _ = _select_client_for_units(usage, clients, 1)
            latency_ms = int((time.time() - t0) * 1000)
            _usage_append(usage, client.get("id") if client else None, None, 1, False, 400, latency_ms)
            _save("usage_events.json", usage)
            return _err("VALIDATION_ERROR", "seed out of range", field="seed")
        seed_val = int(seed)

    # Load stores
    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")
    genreqs = _load("generation_requests.json")
    artifacts = _load("artifacts.json")

    # Auth + quota/rate
    client, deny_reason = _select_client_for_units(usage, clients, 1)
    if clients and client is None:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, None, None, 1, False, 429, latency_ms)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", deny_reason or "rate/quota exceeded")

    client_id = client.get("id") if client else None

    # Resolve model catalog entry (default openai if omitted already applied)
    candidates = [r for r in catalog if isinstance(r, dict) and r.get("modality") == "text_model" and r.get("key") == model_key]
    if not candidates:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client_id, None, 1, False, 404, latency_ms)
        _save("usage_events.json", usage)
        return _err("NOT_FOUND", "requested model key does not exist in text model catalog", key=model_key)

    # Choose active/deprecated first; reject disabled (business rule)
    chosen = None
    for st in ("active", "deprecated"):
        for r in candidates:
            if r.get("status") == st:
                chosen = r
                break
        if chosen:
            break
    if chosen is None:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client_id, None, 1, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "requested model is disabled", key=model_key)

    now = _now_iso()

    # Create generation_request
    gen_id = _new_id("pol_gen")
    gen_row = {
        "id": gen_id,
        "client_id": client_id,
        "tool_name": "respondText",
        "modality": "text",
        "prompt": prompt_s,
        "seed": seed_val,
        "model_catalog_id": chosen.get("id"),
        "model_key": model_key,
        "width": None,
        "height": None,
        "enhance": None,
        "safe": None,
        "output_path": None,
        "file_name": None,
        "format": None,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "started_at": now,
        "completed_at": now,
        "created_at": now,
        "updated_at": now
    }
    genreqs.append(gen_row)

    # Create text artifact
    # Deterministic-ish placeholder text output (offline); must not be empty.
    text_out = f"Model({model_key}) response: {prompt_s[:4000]}"
    art_id = _new_id("pol_art")
    art_row = {
        "id": art_id,
        "generation_request_id": gen_id,
        "artifact_type": "text",
        "mime_type": "text/plain",
        "url": None,
        "base64_data": None,
        "text_content": text_out,
        "file_path": None,
        "file_name": None,
        "file_format": None,
        "size_bytes": len(text_out.encode("utf-8")),
        "status": "available",
        "expires_at": None,
        "created_at": now,
        "updated_at": now
    }
    artifacts.append(art_row)

    # Record usage event linked to generation_request_id
    latency_ms = int((time.time() - t0) * 1000)
    _usage_append(usage, client_id, gen_id, 1, True, 200, latency_ms)

    _save("generation_requests.json", genreqs)
    _save("artifacts.json", artifacts)
    _save("usage_events.json", usage)

    return {
        "generation_request": gen_row,
        "artifact": art_row,
        "output_text": text_out,
        "resolved": {"model": model_key, "seed": seed_val}
    }

def listTextModels(status=None, vendor=None, cursor=None, limit=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _usage_append(usage_rows, client_id, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": None,
            "tool_name": "listTextModels",
            "modality": "catalog",
            "request_units": 0,
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _day_start_utc(dt_aware):
        return dt_aware.replace(hour=0, minute=0, second=0, microsecond=0)

    def _resolve_client_for_call(usage_rows, clients_rows):
        now_dt = _now_utc()
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)

        active = [c for c in clients_rows if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
        def _key(c):
            return _parse_dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        active.sort(key=_key, reverse=True)

        for c in active:
            cid = c.get("id")
            rl = c.get("rate_limit_per_minute")
            if not isinstance(rl, int) or rl < 1 or rl > 6000:
                continue
            calls_60 = 0
            for ev in usage_rows:
                if not isinstance(ev, dict) or ev.get("client_id") != cid:
                    continue
                dt = _parse_dt(ev.get("created_at"))
                if dt and window_start <= dt <= now_dt:
                    calls_60 += 1
            if calls_60 + 1 > rl:
                continue

            qreq = c.get("quota_daily_requests")
            if isinstance(qreq, int) and qreq >= 0:
                used = 0
                for ev in usage_rows:
                    if not isinstance(ev, dict) or ev.get("client_id") != cid:
                        continue
                    dt = _parse_dt(ev.get("created_at"))
                    if dt and dt >= day_start:
                        try:
                            used += int(ev.get("request_units") or 0)
                        except Exception:
                            used += 0
                if used > qreq:
                    continue
            return c
        return None

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c.strip():
            return None
        c = c.strip()
        try:
            pad = '=' * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            pass
        return {"after_id": c}

    def _make_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    allowed_status = {"active", "deprecated", "disabled"}
    allowed_sort_by = {"sort_order", "display_name", "key", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid status", field="status")

    if vendor is not None and not isinstance(vendor, str):
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "vendor must be a string", field="vendor")

    if sortBy is None:
        sortBy = "sort_order"
    if sortOrder is None:
        sortOrder = "asc"

    if not isinstance(sortBy, str) or sortBy not in allowed_sort_by:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortBy", field="sortBy")

    if not isinstance(sortOrder, str) or sortOrder not in allowed_sort_order:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid sortOrder", field="sortOrder")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if limit > 200:
        limit = 200

    cur = _parse_cursor(cursor)
    if cur is None:
        usage = _load("usage_events.json"); clients = _load("clients.json")
        client = _resolve_client_for_call(usage, clients)
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, client.get("id") if client else None, False, 400, latency_ms)
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "invalid cursor", field="cursor")

    usage = _load("usage_events.json")
    clients = _load("clients.json")
    catalog = _load("model_catalog.json")

    client = _resolve_client_for_call(usage, clients)
    if clients and client is None:
        latency_ms = int((time.time() - t0) * 1000)
        _usage_append(usage, None, False, 429, latency_ms)
        _save("usage_events.json", usage)
        return _err("RATE_LIMIT", "No active client available within rate/quota limits")

    client_id = client.get("id") if client else None

    rows = [r for r in catalog if isinstance(r, dict) and r.get("modality") == "text_model"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if vendor is not None:
        rows = [r for r in rows if isinstance(r.get("vendor"), str) and r.get("vendor") == vendor]

    reverse = (sortOrder == "desc")

    def _sort_key(r):
        v = r.get(sortBy)
        if sortBy in ("created_at", "updated_at"):
            return _parse_dt(v) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sortBy == "sort_order":
            try:
                return int(v)
            except Exception:
                return 0
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else str(v)

    rows.sort(key=_sort_key, reverse=reverse)

    start = 0
    if isinstance(cur, dict) and "after_id" in cur:
        after = cur["after_id"]
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == after:
                idx = i
                break
        start = (idx + 1) if idx is not None else 0
    else:
        start = cur

    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor(next_offset) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    _usage_append(usage, client_id, True, 200, latency_ms)
    _save("usage_events.json", usage)

    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def getGenerationRequest(id, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _append_usage(usage_rows, client_id, gen_id, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "getGenerationRequest",
            "modality": "catalog",
            "request_units": 0,
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _day_key_local(dt_utc):
        # Local day boundary not knowable offline; use UTC day consistently.
        return dt_utc.date().isoformat()

    def _enforce_rate_limit(usage_rows, client_row):
        limit = client_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1 or limit > 6000:
            return _err("VALIDATION_ERROR", "client rate_limit_per_minute is invalid", client_id=client_row.get("id"))
        since = _now_utc() - datetime.timedelta(seconds=60)
        n = 0
        for ev in usage_rows if isinstance(usage_rows, list) else []:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != client_row.get("id"):
                continue
            ts = _parse_dt(ev.get("created_at"))
            if ts and ts >= since:
                n += 1
        if n >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for client in rolling 60s window", client_id=client_row.get("id"), limit=limit)
        return None

    def _enforce_daily_quota_requests(usage_rows, client_row):
        quota = client_row.get("quota_daily_requests")
        if not isinstance(quota, int) or quota < 0:
            return _err("VALIDATION_ERROR", "client quota_daily_requests is invalid", client_id=client_row.get("id"))
        today = _day_key_local(_now_utc())
        used = 0
        for ev in usage_rows if isinstance(usage_rows, list) else []:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != client_row.get("id"):
                continue
            ts = _parse_dt(ev.get("created_at"))
            if not ts:
                continue
            if _day_key_local(ts) != today:
                continue
            ru = ev.get("request_units")
            if isinstance(ru, int) and ru > 0:
                used += ru
        if used + 0 > quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", client_id=client_row.get("id"), quota=quota, used=used)
        return None

    def _resolve_client_for_request(clients_rows, gen_row):
        # If request has client_id, enforce visibility to that client.
        # Ambient auth: pick a client that makes the request visible.
        gen_client_id = gen_row.get("client_id")
        if gen_client_id is None:
            # no-auth/local: allow any active client context if exists; else anonymous (None)
            for c in clients_rows if isinstance(clients_rows, list) else []:
                if isinstance(c, dict) and c.get("status") == "active":
                    return c
            return None
        for c in clients_rows if isinstance(clients_rows, list) else []:
            if isinstance(c, dict) and c.get("id") == gen_client_id:
                return c
        # Referenced client missing -> treat as visible anonymous (on delete set null happens, but store may be inconsistent)
        return None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        # still record usage even on validation error (best-effort without client context)
        usage = _load("usage_events.json")
        if isinstance(usage, dict):
            usage_rows = usage.get("rows", [])
        else:
            usage_rows = usage if isinstance(usage, list) else []
        _append_usage(usage_rows, None, None, False, 400, int((time.time() - t0) * 1000))
        _save("usage_events.json", usage if isinstance(usage, dict) else usage_rows)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)

    clients = _load("clients.json")
    clients_rows = clients.get("rows", []) if isinstance(clients, dict) else (clients if isinstance(clients, list) else [])

    gens = _load("generation_requests.json")
    gen_rows = gens.get("rows", []) if isinstance(gens, dict) else (gens if isinstance(gens, list) else [])

    usage = _load("usage_events.json")
    usage_rows = usage.get("rows", []) if isinstance(usage, dict) else (usage if isinstance(usage, list) else [])

    gen = None
    for r in gen_rows:
        if isinstance(r, dict) and r.get("id") == id:
            gen = r
            break

    if not gen:
        _append_usage(usage_rows, None, None, False, 404, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("NOT_FOUND", "generation request not found", id=id)

    # Resolve caller client context so request is "visible"
    client = _resolve_client_for_request(clients_rows, gen)

    # If the resolved client is suspended/deleted, refuse (tool description says FORBIDDEN, but allowed codes exclude it -> UNAUTHORIZED)
    if client is not None:
        st = client.get("status")
        if st in ("suspended", "deleted"):
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 401, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return _err("UNAUTHORIZED", "client is not allowed in current lifecycle state", client_id=client.get("id"), status=st)

        rl_err = _enforce_rate_limit(usage_rows, client)
        if rl_err:
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 429, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return rl_err

        # reading does not consume daily request quota, but quota checks were declared "requests must be rejected when daily quotas would be exceeded"
        # Treat read as 0 units; still validate quota shape for consistency.
        q_err = _enforce_daily_quota_requests(usage_rows, client)
        if q_err and q_err["error"]["code"] == "VALIDATION_ERROR":
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 400, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return q_err

    # Record usage event and return data
    _append_usage(usage_rows, client.get("id") if client else None, gen.get("id"), True, 200, int((time.time() - t0) * 1000))
    if isinstance(usage, dict):
        usage["rows"] = usage_rows
        _save("usage_events.json", usage)
    else:
        _save("usage_events.json", usage_rows)

    # Envelope
    return {
        "generation_request": gen
    }

def listGenerationRequests(status=None, modality=None, toolName=None, modelKey=None, createdAfter=None, createdBefore=None, cursor=None, limit=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- auth resolution (ambient) ----
    clients = _load("clients.json")
    usage = _load("usage_events.json")
    gen = _load("generation_requests.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("timestamp must be a string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _client_day_bounds_utc(now_utc):
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _count_events(client_id, start_dt, end_dt, modality_filter=None):
        cnt = 0
        for e in usage:
            if e.get("client_id") != client_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                edt = _parse_rfc3339(ca)
            except Exception:
                continue
            if not (start_dt <= edt < end_dt):
                continue
            if modality_filter is not None and e.get("modality") != modality_filter:
                continue
            cnt += int(e.get("request_units") or 0)
        return cnt

    def _count_rate_window(client_id, now_utc):
        window_start = now_utc - datetime.timedelta(seconds=60)
        cnt = 0
        for e in usage:
            if e.get("client_id") != client_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                edt = _parse_rfc3339(ca)
            except Exception:
                continue
            if edt >= window_start and edt <= now_utc:
                cnt += int(e.get("request_units") or 0)
        return cnt

    def _pick_ambient_client_for_read():
        # Choose any active client if present; else operate in no-auth mode (client_id=None)
        active = [c for c in clients if c.get("status") == "active"]
        if active:
            return active[0]
        return None

    client = _pick_ambient_client_for_read()

    # ---- input validation ----
    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    valid_modality = {"image", "text", "audio"}
    valid_tool = {"generateImageUrl", "generateImage", "respondText", "respondAudio"}
    valid_sort_by = {"created_at", "updated_at", "started_at", "completed_at"}
    valid_sort_order = {"asc", "desc"}

    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if modality is not None:
        if not isinstance(modality, str) or modality not in valid_modality:
            return _err("VALIDATION_ERROR", "Invalid modality.", field="modality")
    if toolName is not None:
        if not isinstance(toolName, str) or toolName not in valid_tool:
            return _err("VALIDATION_ERROR", "Invalid toolName.", field="toolName")
    if modelKey is not None and not isinstance(modelKey, str):
        return _err("VALIDATION_ERROR", "modelKey must be a string.", field="modelKey")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)

    if sortBy is None:
        sortBy = "created_at"
    if sortOrder is None:
        sortOrder = "desc"
    if not isinstance(sortBy, str) or sortBy not in valid_sort_by:
        return _err("VALIDATION_ERROR", "Invalid sortBy.", field="sortBy")
    if not isinstance(sortOrder, str) or sortOrder not in valid_sort_order:
        return _err("VALIDATION_ERROR", "Invalid sortOrder.", field="sortOrder")

    try:
        ca = _parse_rfc3339(createdAfter) if createdAfter is not None else None
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid createdAfter timestamp.", field="createdAfter", detail=str(e))
    try:
        cb = _parse_rfc3339(createdBefore) if createdBefore is not None else None
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid createdBefore timestamp.", field="createdBefore", detail=str(e))
    if ca is not None and cb is not None and ca > cb:
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore.", field="createdAfter")

    # cursor format: base64url("v1:<offset:int>")
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # ---- rate limit / quota enforcement (if a client exists) ----
    now_utc = datetime.datetime.now(datetime.timezone.utc)
    status_code = 200
    success = True
    err_obj = None

    if client is not None:
        if client.get("status") in ("suspended", "deleted"):
            status_code = 401
            success = False
            err_obj = _err("UNAUTHORIZED", "Client is not allowed (suspended/deleted).", client_id=client.get("id"))
        else:
            rl = int(client.get("rate_limit_per_minute") or 0)
            if rl < 1:
                status_code = 429
                success = False
                err_obj = _err("RATE_LIMIT", "Rate limit exceeded.")
            else:
                rolling = _count_rate_window(client.get("id"), now_utc)
                if rolling + 1 > rl:
                    status_code = 429
                    success = False
                    err_obj = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl, used_last_60s=rolling)

            if success:
                day_start, day_end = _client_day_bounds_utc(now_utc)
                used_requests = _count_events(client.get("id"), day_start, day_end, None)
                quota_req = int(client.get("quota_daily_requests") or 0)
                if quota_req >= 0 and used_requests + 1 > quota_req:
                    status_code = 403
                    success = False
                    err_obj = _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_daily_requests=quota_req, used=used_requests)

                # Catalog modality quotas are not applicable; listing is "catalog" but this is a list tool; still counts in requests above

    # ---- apply read ----
    rows = []
    total = 0
    next_cursor = None
    has_more = False

    if success:
        # visibility: if we have a client context, only that client's requests; else only those with client_id null
        if client is not None:
            visible = [r for r in gen if r.get("client_id") == client.get("id")]
        else:
            visible = [r for r in gen if r.get("client_id") is None]

        # filters
        def _row_dt(field):
            v = field
            if not isinstance(v, str) or v.strip() == "":
                return None
            try:
                return _parse_rfc3339(v)
            except Exception:
                return None

        filtered = []
        for r in visible:
            if status is not None and r.get("status") != status:
                continue
            if modality is not None and r.get("modality") != modality:
                continue
            if toolName is not None and r.get("tool_name") != toolName:
                continue
            if modelKey is not None and r.get("model_key") != modelKey:
                continue
            if ca is not None:
                rca = _row_dt(r.get("created_at"))
                if rca is None or rca < ca:
                    continue
            if cb is not None:
                rcb = _row_dt(r.get("created_at"))
                if rcb is None or rcb >= cb:
                    continue
            filtered.append(r)

        # sorting
        reverse = (sortOrder == "desc")

        def _sort_key(r):
            dt = _row_dt(r.get(sortBy))
            # None sorts last when desc? We'll normalize to epoch for missing, but stable.
            if dt is None:
                # For desc, missing should go last; for asc, missing should go last too.
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt

        # Sort with secondary key id for stability
        filtered.sort(key=lambda r: (_sort_key(r), r.get("id") or ""), reverse=reverse)

        total = len(filtered)
        page = filtered[offset:offset + limit]
        rows = page

        new_offset = offset + len(page)
        has_more = new_offset < total
        if has_more:
            raw = f"v1:{new_offset}".encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- usage event ----
    usage_events = usage
    def _new_id(prefix):
        # deterministic enough: prefix + utc millis + hash
        ms = int(time.time() * 1000)
        rnd = hashlib.sha256(f"{prefix}:{ms}:{os.getpid()}".encode("utf-8")).hexdigest()[:12]
        return f"{prefix}_{ms}_{rnd}"

    latency_ms = int((time.time() - t0) * 1000)
    ev = {
        "id": _new_id("use"),
        "client_id": client.get("id") if client is not None else None,
        "generation_request_id": None,
        "tool_name": "listGenerationRequests",  # not in enum but tool set omits; map to closest catalog? schema doesn't include; must use declared enums.
        "modality": "catalog",
        "request_units": 1,
        "success": bool(success),
        "http_status": int(status_code),
        "latency_ms": int(latency_ms),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    # Conform to enum: tool_name must be one of listImageModels/listTextModels/listAudioVoices or generation tools.
    # This tool isn't in schema enum; record it as a 0-unit catalog event under listTextModels for accounting parity.
    ev["tool_name"] = "listTextModels"
    ev["modality"] = "catalog"
    ev["request_units"] = 0

    usage_events.append(ev)
    _save("usage_events.json", usage_events)

    if not success:
        return err_obj

    return {
        "data": rows,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        },
    }

def cancelGenerationRequest(id, reason=None, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _append_usage(usage_rows, client_id, gen_id, success, http_status, latency_ms):
        now = _now_iso()
        usage_rows.append({
            "id": _new_id("pol_ue"),
            "client_id": client_id,
            "generation_request_id": gen_id,
            "tool_name": "cancelGenerationRequest",
            "modality": "catalog",
            "request_units": 0,
            "success": bool(success),
            "http_status": int(http_status) if http_status is not None else None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now,
            "updated_at": now
        })

    def _day_key_local(dt_utc):
        return dt_utc.date().isoformat()

    def _enforce_rate_limit(usage_rows, client_row):
        limit = client_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1 or limit > 6000:
            return _err("VALIDATION_ERROR", "client rate_limit_per_minute is invalid", client_id=client_row.get("id"))
        since = _now_utc() - datetime.timedelta(seconds=60)
        n = 0
        for ev in usage_rows if isinstance(usage_rows, list) else []:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != client_row.get("id"):
                continue
            ts = _parse_dt(ev.get("created_at"))
            if ts and ts >= since:
                n += 1
        if n >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for client in rolling 60s window", client_id=client_row.get("id"), limit=limit)
        return None

    def _enforce_daily_quota_requests(usage_rows, client_row):
        quota = client_row.get("quota_daily_requests")
        if not isinstance(quota, int) or quota < 0:
            return _err("VALIDATION_ERROR", "client quota_daily_requests is invalid", client_id=client_row.get("id"))
        today = _day_key_local(_now_utc())
        used = 0
        for ev in usage_rows if isinstance(usage_rows, list) else []:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != client_row.get("id"):
                continue
            ts = _parse_dt(ev.get("created_at"))
            if not ts:
                continue
            if _day_key_local(ts) != today:
                continue
            ru = ev.get("request_units")
            if isinstance(ru, int) and ru > 0:
                used += ru
        if used + 0 > quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", client_id=client_row.get("id"), quota=quota, used=used)
        return None

    def _resolve_client_for_request(clients_rows, gen_row):
        gen_client_id = gen_row.get("client_id")
        if gen_client_id is None:
            for c in clients_rows if isinstance(clients_rows, list) else []:
                if isinstance(c, dict) and c.get("status") == "active":
                    return c
            return None
        for c in clients_rows if isinstance(clients_rows, list) else []:
            if isinstance(c, dict) and c.get("id") == gen_client_id:
                return c
        return None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        usage = _load("usage_events.json")
        usage_rows = usage.get("rows", []) if isinstance(usage, dict) else (usage if isinstance(usage, list) else [])
        _append_usage(usage_rows, None, None, False, 400, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)

    if reason is not None and not isinstance(reason, str):
        usage = _load("usage_events.json")
        usage_rows = usage.get("rows", []) if isinstance(usage, dict) else (usage if isinstance(usage, list) else [])
        _append_usage(usage_rows, None, None, False, 400, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("VALIDATION_ERROR", "reason must be a string when provided", reason=reason)

    clients = _load("clients.json")
    clients_rows = clients.get("rows", []) if isinstance(clients, dict) else (clients if isinstance(clients, list) else [])

    gens = _load("generation_requests.json")
    gen_rows = gens.get("rows", []) if isinstance(gens, dict) else (gens if isinstance(gens, list) else [])

    usage = _load("usage_events.json")
    usage_rows = usage.get("rows", []) if isinstance(usage, dict) else (usage if isinstance(usage, list) else [])

    gen = None
    gen_idx = None
    for i, r in enumerate(gen_rows):
        if isinstance(r, dict) and r.get("id") == id:
            gen = r
            gen_idx = i
            break

    if not gen:
        _append_usage(usage_rows, None, None, False, 404, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("NOT_FOUND", "generation request not found", id=id)

    client = _resolve_client_for_request(clients_rows, gen)

    if client is not None:
        st = client.get("status")
        if st in ("suspended", "deleted"):
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 401, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return _err("UNAUTHORIZED", "client is not allowed in current lifecycle state", client_id=client.get("id"), status=st)

        rl_err = _enforce_rate_limit(usage_rows, client)
        if rl_err:
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 429, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return rl_err

        q_err = _enforce_daily_quota_requests(usage_rows, client)
        if q_err and q_err["error"]["code"] == "VALIDATION_ERROR":
            _append_usage(usage_rows, client.get("id"), gen.get("id"), False, 400, int((time.time() - t0) * 1000))
            if isinstance(usage, dict):
                usage["rows"] = usage_rows
                _save("usage_events.json", usage)
            else:
                _save("usage_events.json", usage_rows)
            return q_err

    # Lifecycle transition enforcement
    status = gen.get("status")
    if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _append_usage(usage_rows, client.get("id") if client else None, gen.get("id"), False, 409, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("INVALID_TRANSITION", "generation request has invalid status value", id=id, status=status)

    if status not in ("queued", "running"):
        # Refuse cancellation once terminal
        _append_usage(usage_rows, client.get("id") if client else None, gen.get("id"), False, 409, int((time.time() - t0) * 1000))
        if isinstance(usage, dict):
            usage["rows"] = usage_rows
            _save("usage_events.json", usage)
        else:
            _save("usage_events.json", usage_rows)
        return _err("CONFLICT", "Cannot cancel a generation request once it is succeeded/failed/cancelled", id=id, status=status)

    # Perform mutation
    now = _now_iso()
    gen_mut = dict(gen)
    gen_mut["status"] = "cancelled"
    gen_mut["updated_at"] = now
    # Business rule: allow late-populated error_message. Store reason there to persist audit.
    if isinstance(reason, str) and reason.strip():
        # keep any existing error_message by appending
        prev = gen_mut.get("error_message")
        if isinstance(prev, str) and prev.strip():
            gen_mut["error_message"] = (prev.strip() + " | cancellation_reason: " + reason.strip())[:20000]
        else:
            gen_mut["error_message"] = ("cancellation_reason: " + reason.strip())[:20000]
        if not gen_mut.get("error_code"):
            gen_mut["error_code"] = "USER_CANCELLED"
    gen_mut["completed_at"] = gen_mut.get("completed_at") or now

    # Write back
    gen_rows[gen_idx] = gen_mut
    if isinstance(gens, dict):
        gens["rows"] = gen_rows
        _save("generation_requests.json", gens)
    else:
        _save("generation_requests.json", gen_rows)

    _append_usage(usage_rows, client.get("id") if client else None, gen_mut.get("id"), True, 200, int((time.time() - t0) * 1000))
    if isinstance(usage, dict):
        usage["rows"] = usage_rows
        _save("usage_events.json", usage)
    else:
        _save("usage_events.json", usage_rows)

    return {
        "generation_request": gen_mut
    }

def getIdentity(includeUsage=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0202000" if __import__("os").path.isdir("./environment_mix/0202000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if includeUsage is None:
        includeUsage = True
    if not isinstance(includeUsage, bool):
        return _err("VALIDATION_ERROR", "includeUsage must be a boolean.", field="includeUsage")

    clients = _load("clients.json")
    usage = _load("usage_events.json")

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = hashlib.sha256(f"{prefix}:{ms}:{os.getpid()}".encode("utf-8")).hexdigest()[:12]
        return f"{prefix}_{ms}_{rnd}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        ss = s
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _client_day_bounds_utc(now_utc):
        start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _count_events(client_id, start_dt, end_dt, modality_filter=None):
        cnt = 0
        for e in usage:
            if e.get("client_id") != client_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                edt = _parse_rfc3339(ca)
            except Exception:
                continue
            if not (start_dt <= edt < end_dt):
                continue
            if modality_filter is not None and e.get("modality") != modality_filter:
                continue
            cnt += int(e.get("request_units") or 0)
        return cnt

    def _count_rate_window(client_id, now_utc):
        window_start = now_utc - datetime.timedelta(seconds=60)
        cnt = 0
        for e in usage:
            if e.get("client_id") != client_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                edt = _parse_rfc3339(ca)
            except Exception:
                continue
            if edt >= window_start and edt <= now_utc:
                cnt += int(e.get("request_units") or 0)
        return cnt

    # getIdentity requires a credential in real service, but tool has none.
    # Under the contract, authentication is ambient: resolve a working active client.
    active = [c for c in clients if c.get("status") == "active"]
    if not active:
        # record usage event (no client)
        ev = {
            "id": _new_id("use"),
            "client_id": None,
            "generation_request_id": None,
            "tool_name": "listTextModels",
            "modality": "catalog",
            "request_units": 0,
            "success": False,
            "http_status": 401,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "No authenticated client available.")

    client = active[0]
    if client.get("status") in ("suspended", "deleted"):
        # record usage
        ev = {
            "id": _new_id("use"),
            "client_id": client.get("id"),
            "generation_request_id": None,
            "tool_name": "listTextModels",
            "modality": "catalog",
            "request_units": 0,
            "success": False,
            "http_status": 401,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "Client is not allowed (suspended/deleted).", client_id=client.get("id"))

    identity = {
        "id": client.get("id"),
        "display_name": client.get("display_name"),
        "status": client.get("status"),
        "notes": client.get("notes"),
        "created_at": client.get("created_at"),
        "updated_at": client.get("updated_at"),
        "scopes": ["image", "text", "audio", "catalog"],
        "limits": {
            "quota_daily_requests": client.get("quota_daily_requests"),
            "quota_daily_images": client.get("quota_daily_images"),
            "quota_daily_text": client.get("quota_daily_text"),
            "quota_daily_audio": client.get("quota_daily_audio"),
            "rate_limit_per_minute": client.get("rate_limit_per_minute"),
        },
    }

    if includeUsage:
        day_start, day_end = _client_day_bounds_utc(now)
        identity["usage"] = {
            "today": {
                "requests": _count_events(client.get("id"), day_start, day_end, None),
                "images": _count_events(client.get("id"), day_start, day_end, "image"),
                "text": _count_events(client.get("id"), day_start, day_end, "text"),
                "audio": _count_events(client.get("id"), day_start, day_end, "audio"),
                "catalog_units": _count_events(client.get("id"), day_start, day_end, "catalog"),
            },
            "rate_limit_window": {
                "used_last_60s": _count_rate_window(client.get("id"), now),
                "window_seconds": 60,
            },
        }

    # record usage event (0 units)
    ev = {
        "id": _new_id("use"),
        "client_id": client.get("id"),
        "generation_request_id": None,
        "tool_name": "listTextModels",
        "modality": "catalog",
        "request_units": 0,
        "success": True,
        "http_status": 200,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    usage.append(ev)
    _save("usage_events.json", usage)

    return {"data": identity}
